const input = $json.body ?? $json;
if (input.schema !== 'nse-daily-ingest-whatsapp.v1' || input.event_type !== 'nse.daily.files.missing.v1' || !input.event_id || !input.trade_date || !input.payload) throw new Error('INVALID_NSE_INGEST_EVENT');
const p = input.payload;
if (!Number.isInteger(p.expected_files) || !Number.isInteger(p.available_files) || !Number.isInteger(p.missing_count) || !Array.isArray(p.missing_files) || p.missing_count < 1) throw new Error('INVALID_NSE_MISSING_FILE_PAYLOAD');
const state = $getWorkflowStaticData('global');
const cfg = state.deliveryConfig ?? {};
if (!cfg.gatewayUrl || !cfg.chatId) throw new Error('NSE_INGEST_DELIVERY_CONFIG_MISSING');
state.seen = state.seen ?? {};
const now = Date.now(); for (const [id, at] of Object.entries(state.seen)) if (now - Number(at) > 172800000) delete state.seen[id];
if (state.seen[input.event_id]) return [{json:{send:false,event_id:input.event_id,suppression_reason:'DUPLICATE_EVENT'}}];
const names = p.missing_files.slice(0, 20).map((item) => '• ' + item.report_id + ' — ' + item.file_name);
if (p.missing_count > 20) names.push('• +' + (p.missing_count - 20) + ' more files');
const lines = ['*NSE DAILY DATA — FILES MISSING*','Trade date *' + input.trade_date + '* · ' + p.available_files + '/' + p.expected_files + ' available','Missing *' + p.missing_count + '*',...names,'Action: ' + (p.action || 'Review and rerun missing reports.'),'Data operations alert · no trade was created'];
const message = lines.join('\n'); if (message.length > 1800) throw new Error('NSE_INGEST_MESSAGE_TOO_LONG');
return [{json:{send:true,event_id:input.event_id,event_type:input.event_type,whatsapp_message:message,gateway_url:cfg.gatewayUrl,chat_id:cfg.chatId}}];
